import math

EASY_TOPICS = {"combinatorics", "number_theory"}


def _majority_vote(sample_list):
    counts = {}
    for a, _ in sample_list:
        counts[a] = counts.get(a, 0) + 1
    return max(counts.items(), key=lambda kv: kv[1])[0]


def _score_weighted_vote(sample_list, temp=0.7):
    max_score = max(s for _, s in sample_list)
    sums = {}
    for a, s in sample_list:
        sums[a] = sums.get(a, 0.0) + math.exp((s - max_score) / temp)
    return max(sums.items(), key=lambda kv: kv[1])[0]


def run(env):
    questions = env.questions
    n = len(questions)
    n_variants = env.n_variants
    budget = env.budget

    easy_qids = [q["id"] for q in questions if q["topic"] in EASY_TOPICS]
    hard_qids = [q["id"] for q in questions if q["topic"] not in EASY_TOPICS]

    # Verifier score is reliable (helps a lot) on combinatorics/number_theory,
    # and it converges fast, so a modest fixed sample count suffices there.
    # It is unreliable (actively misleading) on algebra/geometry, where plain
    # majority vote works better and benefits from more raw samples. So we
    # give the "easy" topics a small fixed budget and push everything else
    # (the shared pooled budget) toward the "hard" topics.
    N_EASY = 4
    easy_cost = N_EASY * len(easy_qids)
    remaining = budget - easy_cost
    if hard_qids:
        n_hard_base = max(1, remaining // len(hard_qids))
    else:
        n_hard_base = 0

    samples = {q["id"]: [] for q in questions}
    next_variant = {q["id"]: 0 for q in questions}

    def take(qid):
        if env.left() <= 0:
            return False
        v = next_variant[qid] % n_variants
        a, s = env.sample(qid, v)
        samples[qid].append((a, s))
        next_variant[qid] += 1
        return True

    for qid in easy_qids:
        for _ in range(N_EASY):
            if not take(qid):
                break

    for qid in hard_qids:
        for _ in range(n_hard_base):
            if not take(qid):
                break

    # Spend any leftover pooled budget on the hard questions (round robin),
    # since extra samples help majority vote there more than on easy topics.
    idx = 0
    while env.left() > 0 and hard_qids:
        qid = hard_qids[idx % len(hard_qids)]
        if not take(qid):
            break
        idx += 1

    # If somehow there's still budget left (e.g. no hard questions), spend it
    # on easy questions.
    idx = 0
    while env.left() > 0 and easy_qids:
        qid = easy_qids[idx % len(easy_qids)]
        if not take(qid):
            break
        idx += 1

    out = {}
    for q in questions:
        qid = q["id"]
        s = samples[qid]
        if not s:
            continue
        if q["topic"] in EASY_TOPICS:
            out[qid] = _score_weighted_vote(s)
        else:
            out[qid] = _majority_vote(s)

    env.submit(out)

