import heapq
import math


def _confidence(sample_list, temp):
    # sample_list: list of (answer, score). Returns (confidence_margin, weighted_sums)
    if not sample_list:
        return 0.0, {}
    max_score = max(s for _, s in sample_list)
    sums = {}
    for a, s in sample_list:
        sums[a] = sums.get(a, 0.0) + math.exp((s - max_score) / temp)
    vals = sorted(sums.values(), reverse=True)
    total = sum(vals)
    if len(vals) == 1:
        margin = 1.0
    else:
        margin = (vals[0] - vals[1]) / total if total > 0 else 0.0
    return margin, sums


def run(env):
    questions = env.questions
    n = len(questions)
    qids = [q["id"] for q in questions]
    n_variants = env.n_variants
    budget = env.budget
    avg = budget / n if n else 0

    TEMP = 0.7
    phase1 = max(1, min(n_variants, int(round(avg / 2))))
    cap = max(phase1, min(20, int(round(avg * 2.5))))

    samples = {qid: [] for qid in qids}
    next_variant = {qid: 0 for qid in qids}

    def take_sample(qid):
        v = next_variant[qid] % n_variants
        a, s = env.sample(qid, v)
        samples[qid].append((a, s))
        next_variant[qid] += 1

    # Phase 1: spend a fixed number of samples per question, cycling variants
    for qid in qids:
        for _ in range(phase1):
            if env.left() <= 0:
                break
            take_sample(qid)

    # Phase 2: adaptively spend the remaining pooled budget on the least
    # confident questions (lowest margin between top two weighted answers),
    # up to a cap per question so a single hard question can't starve others.
    heap = []
    version = {qid: 0 for qid in qids}
    for qid in qids:
        if len(samples[qid]) < cap:
            margin, _ = _confidence(samples[qid], TEMP)
            heapq.heappush(heap, (margin, qid, version[qid]))

    while env.left() > 0 and heap:
        margin, qid, ver = heapq.heappop(heap)
        if ver != version[qid]:
            continue  # stale entry, state has changed since pushed
        if len(samples[qid]) >= cap:
            continue
        take_sample(qid)
        version[qid] += 1
        if len(samples[qid]) < cap:
            new_margin, _ = _confidence(samples[qid], TEMP)
            heapq.heappush(heap, (new_margin, qid, version[qid]))

    # Spend any leftover budget (e.g. if all questions hit the cap) on the
    # globally least confident questions regardless of cap.
    while env.left() > 0:
        worst_qid = None
        worst_margin = None
        for qid in qids:
            margin, _ = _confidence(samples[qid], TEMP)
            if worst_margin is None or margin < worst_margin:
                worst_margin = margin
                worst_qid = qid
        if worst_qid is None:
            break
        take_sample(worst_qid)

    out = {}
    for qid in qids:
        _, sums = _confidence(samples[qid], TEMP)
        if sums:
            out[qid] = max(sums.items(), key=lambda kv: kv[1])[0]
    env.submit(out)
